window.docContents[156].resolve({"/Elementary-Functions/___4___48-Software/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___48-Software--___4___48-Software--___4___48_LPAR_v_RPAR_-Testing":{"contents":"The testing resource is Cody (1993a), Fortran.\n\nCody (1993a) is listed as a Fortran testing resource for the functions in\nthe software bibliography.\n\nThe neighboring DLMF pages are §4.47 Approximations\nand §5 Gamma Function. Since §4.48 contains\nsoftware references rather than displayed mathematics, its Lean companion\nmodule contains no theorem declaration.\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.48 Software\u0009§4.48 Software","header":"§4.48(v) Testing","id":"/Elementary-Functions/___4___48-Software/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___48-Software--___4___48-Software--___4___48_LPAR_v_RPAR_-Testing"}});